code_sketch:
struct WebLink: Codable { let rel: String; let href: URL; let method: String? }
struct OrderPage: Codable { let order: Order; let links: [WebLink] }   // _links carrier

let base = URL(string: "https://api.example.com/orders/42")!
let payment = WebLink(rel: "payment", href: URL(string: "payment", relativeTo: base)!.absoluteURL, method: "GET")
let body = try JSONEncoder().encode(OrderPage(order: order, links: [payment]))   // transfer

let page = try JSONDecoder().decode(OrderPage.self, from: body)
guard let link = page.links.first(where: { $0.rel == "payment" && $0.method == "GET" }) else { return }
let (data, response) = try await URLSession.shared.data(from: link.href)   // dereference
guard let http = response as? HTTPURLResponse, 200...299 ~= http.statusCode else { throw LinkError.dead }
// naive URL(string: "payment") has no scheme/host and URLSession fails; resolve with URL(string:relativeTo:)
